def fetch_with_retries(fetch_fn, max_retries=3):
    """Try calling fetch_fn, retrying up to max_retries times on failure.
    Returns the result on first success, or raises the last exception if all attempts fail.
    """
    last_exception = None
    for attempt in range(max_retries):
        try:
            return fetch_fn()
        except Exception as e:
            last_exception = e
    raise last_exception
